edits.old:
for (std::size_t i = 2; i <= N; ++i) prime[i] = true;
for (std::size_t p = 2; p * p <= N; ++p) {
    if (!prime[p]) continue;
    for (std::size_t multiple = p * p; multiple <= N; multiple += p) prime[multiple] = false;
}
return prime;

edits.new:
for (std::size_t i = 2; i <= N; ++i) {
    bool is_prime = true;
    for (std::size_t d = 2; d < i; ++d) {
        if (i % d == 0) {
            is_prime = false;
            break;
        }
    }
    prime[i] = is_prime;
}
return prime;
